const data = $input.first().json;

const now = new Date().toISOString();

return [{
  json: {
    bandejacorreofechaingesta: now,
    bandejacorreofecharecepcionorigen: data.fechaRecepcion || data.date || now,
    bandejacorreofuenteorigen: data.fuenteOrigen || 'gmail',
    bandejacorreoemailorigen: data.emailOrigen || data.from || '',
    bandejacorreoemaildestinatario: data.emailDestinatario || data.to || 'contacto@teknoconecta.com',
    bandejacorreoidmensajegmail: data.idMensajeGmail || data.messageId || '',
    bandejacorreopayloadcrudo: JSON.stringify(data.payload || data),
    bandejacorreotextoinformacion: [
      'Asunto: ' + (data.asunto || data.subject || ''),
      'Remitente: ' + (data.emailOrigen || data.from || ''),
      '',
      (data.texto || data.body || data.text || '')
    ].join('\n'),
    estadobandejacorreoid: 1,
    bandejacorreointentos: 0
  }
}];
